package com.dlt.predictor.prediction;import com.dlt.predictor.api.ApiResponse;import com.dlt.predictor.lottery.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/v1/dlt/predictions") public class PredictionController{private final DrawStore store;private final RecommendationEngine engine=new RecommendationEngine();PredictionController(DrawStore s){store=s;}@PostMapping public ApiResponse<RecommendationResult>create(@Valid @RequestBody PredictionRequest req){DltNumbers input="CUSTOM_NUMBERS".equals(req.inputType())?DltNumbers.of(req.frontNumbers(),req.backNumbers()):store.all().stream().findFirst().orElseThrow(()->new IllegalArgumentException("没有开奖数据")).numbers();var similar=store.all().stream().filter(d->!d.numbers().equals(input)).map(d->new SimilarDraw(d.id(),d.issueNo(),d.drawDate(),d.numbers(),cosine(FeatureEncoder.encode(input),FeatureEncoder.encode(d.numbers())))).sorted(Comparator.comparingDouble(SimilarDraw::similarity).reversed()).limit(Math.min(req.topK(),10)).toList();return ApiResponse.ok(engine.recommend(similar,LocalDate.now()));}private double cosine(float[]a,float[]b){double s=0;for(int i=0;i<a.length;i++)s+=a[i]*b[i];return s;}}
record PredictionRequest(@NotBlank String inputType,@Min(1)@Max(10) int topK,List<Integer>frontNumbers,List<Integer>backNumbers){}
